/* A single state drives all three views. Meshes remain an opt-in enhancement. */
(()=>{'use strict';const form=document.querySelector('[data-phone-size]');if(!form)return;
 const a=form.elements.a,b=form.elements.b,overlay=form.elements.overlay,folded=form.elements.folded,foldedOption=form.querySelector('[data-phone-folded-option]'),scale=form.querySelector('[data-phone-scale]'),output=form.querySelector('output'),models=form.querySelector('[data-phone-comparison]'),template=document.querySelector('[data-phone-view-templates]'),facts=form.querySelector('[data-phone-measurements]'),specs=form.querySelector('[data-phone-specs]');let phones=[],previous='',view='size',modeTouched=false;
 const core=p=>{const values=Object.fromEntries(Object.entries(p.fields).map(([k,f])=>[k,f.value]));if(folded.checked&&values.foldedHeight){values.height=values.foldedHeight;values.width=values.foldedWidth;values.depth=values.foldedDepth}return values};
 const name=p=>p.name+(folded.checked&&p.fields.foldedHeight?.value?' (folded)':'');
 function state(replace=true){const url=new URL(location.href);for(const [key,value]of [['a',a.value],['b',b.value],['view',view]])url.searchParams.set(key,value);for(const key of ['overlay','folded']){if(form.elements[key].checked)url.searchParams.set(key,'1');else url.searchParams.delete(key)}if(replace)history.replaceState(null,'',url);return url.href}
 function mode(value,persist=true){view=['size','design','specs'].includes(value)?value:'size';form.dataset.phoneActiveView=view;for(const button of form.querySelectorAll('[data-phone-mode]'))button.setAttribute('aria-pressed',String(button.dataset.phoneMode===view));form.querySelector('[data-phone-design]').hidden=view!=='design';form.querySelector('[data-phone-size-view]').hidden=view!=='size';form.querySelector('.phone-measurements').hidden=view!=='size';form.querySelector('[data-phone-spec-view]').hidden=view!=='specs';output.hidden=view!=='size';form.querySelector('[data-phone-linked]').closest('label').hidden=view!=='design';form.querySelector('[data-phone-mode-help]').textContent={size:'Compare verified body dimensions at the same scale.',design:'Open a model, then drag or use the angle buttons.',specs:'Compare sourced specifications and support commitments.'}[view];if(persist)state()}
 function cell(row,text,heading=false){const c=document.createElement(heading?'th':'td');if(heading)c.scope='row';c.textContent=text;row.append(c);return c}
 function table(target,pair,rows,caption){const t=document.createElement('table');t.className='phone-dimensions-table';if(caption){const c=document.createElement('caption');c.textContent=caption;t.append(c)}const head=document.createElement('thead'),r=document.createElement('tr');for(const text of ['Specification',...pair.map(name)]){const th=document.createElement('th');th.scope='col';th.textContent=text;r.append(th)}head.append(r);t.append(head);const body=document.createElement('tbody');for(const [label,values]of rows){const tr=document.createElement('tr');cell(tr,label,true);for(const v of values)cell(tr,v??'Not verified');body.append(tr)}t.append(body);target.replaceChildren(t);return body}
 function draw(persist=true){const pair=[a,b].map(s=>phones.find(p=>p.id===s.value));if(pair.some(p=>!p))return;foldedOption.hidden=!pair.some(p=>p.fields.foldedHeight?.value);if(foldedOption.hidden)folded.checked=false;const [first,second]=pair,values=pair.map(core),maxHeight=Math.max(...values.map(c=>c.height||0));scale.replaceChildren();
  for(const [i,p]of pair.entries()){const f=values[i],fig=document.createElement('figure'),cap=document.createElement('figcaption');cap.textContent=name(p);if(Number.isFinite(f.height)&&Number.isFinite(f.width)){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),rect=document.createElementNS(svg.namespaceURI,'rect');svg.setAttribute('viewBox',`0 0 ${f.width} ${maxHeight}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',`${p.name}, ${f.height} mm tall and ${f.width} mm wide`);svg.style.color=i?'var(--phone-secondary)':'var(--accent-ink)';for(const [k,v]of Object.entries({x:1,y:maxHeight-f.height+1,width:f.width-2,height:f.height-2,rx:7,fill:'currentColor','fill-opacity':.08,stroke:'currentColor','stroke-width':1.3}))rect.setAttribute(k,String(v));svg.append(rect);fig.append(svg)}else{const n=document.createElement('p');n.textContent='Body dimensions are not verified.';fig.append(n)}fig.append(cap);scale.append(fig)}scale.classList.toggle('overlay',overlay.checked);
  const selection=pair.map(p=>p.id).join(',');if(selection!==previous&&models&&template){const grid=document.createElement('section');grid.className='phone-comparison-views';grid.setAttribute('aria-label','Selected phone viewing angles');for(const p of pair){const card=[...template.content.querySelectorAll('[data-phone-preview]')].find(el=>el.dataset.phonePreview===p.id)?.closest('article');if(card)grid.append(card.cloneNode(true))}models.replaceChildren(grid);previous=selection;document.dispatchEvent(new Event('pcp:phone-selection'))}
  table(facts,pair,[['height','Height','mm'],['width','Width','mm'],['depth','Thickness','mm'],['weight','Weight','g']].map(([key,label,unit])=>[label,values.map(c=>Number.isFinite(c[key])?c[key]+' '+unit:'Not verified')]));
  const rows=[['diagonal','Screen diagonal','in'],['resolution','Screen resolution',''],['soc','Processor',''],['ram','Memory','GB'],['storage','Storage options',''],['batteryTypical','Typical battery','mAh'],['usbData','USB data','']].filter(([key])=>pair.some(p=>p.fields[key]?.value!=null)).map(([key,label,unit])=>[label,pair.map(p=>{const v=p.fields[key]?.value;return v==null?'Not verified':String(v)+(unit?' '+unit:'')})]);rows.push(['Software support',pair.map(p=>p.support?.commitment||'Commitment not verified')]);const body=table(specs,pair,rows,'Specifications');const sourceRow=document.createElement('tr');cell(sourceRow,'Manufacturer sources',true);for(const p of pair){const td=cell(sourceRow,'');const unique=[...new Set(Object.values(p.fields).map(f=>f.source).filter(Boolean))];for(const [i,url]of unique.entries()){if(!/^https:\/\//.test(url))continue;const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.textContent=unique.length===1?'Specifications':'Source '+(i+1);td.append(link,document.createTextNode(' '))}if(p.support?.source){const link=document.createElement('a');link.href=p.support.source;link.textContent='Support policy';link.target='_blank';link.rel='noopener';td.append(link)}}body.append(sourceRow);
  const pieces=[];let compared=0;for(const [key,positive,negative,unit]of [['height','taller','shorter','mm'],['width','wider','narrower','mm'],['depth','thicker','thinner','mm'],['weight','heavier','lighter','g']]){if(!Number.isFinite(values[0][key])||!Number.isFinite(values[1][key]))continue;compared++;const n=values[1][key]-values[0][key];if(n)pieces.push(`${Number(Math.abs(n).toFixed(2))} ${unit} ${n>0?positive:negative}`)}output.textContent=pieces.length?`${second.name} is ${pieces.join(', ')} than ${first.name}.`:compared?'The available recorded dimensions match. Unverified values are omitted.':'There are not enough verified dimensions to calculate a difference.';if(persist)state();
 }
 function restore(){const q=new URLSearchParams(location.search);for(const [key,select]of [['a',a],['b',b]]){const id=q.get(key);if(phones.some(p=>p.id===id))select.value=id}overlay.checked=q.get('overlay')==='1';folded.checked=q.get('folded')==='1';draw(false);mode(q.get('view')||'size',false);for(const s of [a,b])s.dispatchEvent(new Event('change',{bubbles:true}))}
 // View controls work immediately, even while the small specification file is
 // loading. Opening a view never moves focus into a text field or keyboard.
 const modeButtons=[...form.querySelectorAll('[data-phone-mode]')];
 for(const [index,button]of modeButtons.entries()){
  button.addEventListener('click',()=>{modeTouched=true;mode(button.dataset.phoneMode)});
  button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?modeButtons.length-1:(index+(event.key==='ArrowRight'?1:-1)+modeButtons.length)%modeButtons.length;modeTouched=true;mode(modeButtons[next].dataset.phoneMode);modeButtons[next].focus()});
 }
 const initialQuery=new URLSearchParams(location.search);for(const [key,select]of [['a',a],['b',b]]){const id=initialQuery.get(key);if([...select.options].some(option=>option.value===id))select.value=id}
 mode(initialQuery.get('view')||'size',false);
 form.querySelector('[data-phone-share]').addEventListener('click',async()=>{const status=form.querySelector('[data-phone-share-status]');try{await navigator.clipboard.writeText(state(false));status.textContent='Link copied.'}catch{status.textContent='Copy the address from your browser to share this comparison.'}});
 fetch('/data/phones-v1.json').then(r=>{if(!r.ok)throw Error('Specifications are temporarily unavailable.');return r.json()}).then(data=>{if(!Array.isArray(data.phones)||!data.phones.length)throw Error('Specifications are temporarily unavailable.');phones=data.phones;const selectedMode=view;restore();if(modeTouched)mode(selectedMode);a.addEventListener('change',()=>draw());b.addEventListener('change',()=>draw());overlay.addEventListener('change',()=>draw());folded.addEventListener('change',()=>draw());form.querySelector('[data-phone-swap]').addEventListener('click',()=>{[a.value,b.value]=[b.value,a.value];draw();for(const s of [a,b])s.dispatchEvent(new Event('change',{bubbles:true}))});window.addEventListener('popstate',restore)}).catch(()=>{const error=document.createElement('p');error.className='phone-comparison-error';error.setAttribute('role','alert');error.textContent='Phone specifications could not load. Reload this page to try again, or browse individual phones below.';const link=document.createElement('a');link.href='/phones/';link.textContent='Browse phones';error.append(document.createTextNode(' '),link);form.prepend(error);output.textContent='Dimensions are temporarily unavailable.'});
})();
